import json
@responses.activate
def run():
    def auth_callback(request):
        data = json.loads(request.body)
        if data.get('token') == 'valid':
            return (200, {}, json.dumps({'auth': True}))
        return (401, {}, json.dumps({'auth': False}))
    responses.add_callback(responses.POST, 'http://api.io/auth', callback=auth_callback)
    r = requests.post('http://api.io/auth', json={'token': 'invalid'})
    return r.status_code
print(run())

