import json
@responses.activate
def run():
    def complex_callback(request):
        try:
            data = json.loads(request.body)
            return (200, {}, json.dumps({'success': True, 'id': data['id']}))
        except:
            return (400, {}, json.dumps({'success': False}))
    responses.add_callback(responses.POST, 'http://api.io/process', callback=complex_callback)
    r = requests.post('http://api.io/process', json={'id': 123})
    return json.loads(r.text)['id']
print(run())

